import { FieldItem, TableItem } from '@/types/business';
import { observable } from 'mobx';


interface InfoItem {
    fields: FieldItem[];
    tables: TableItem[];
}

class Store {

    /** 所有字段数据 */
    info: Record<string, InfoItem> = {}

    /**
     * 生成infoData 
     */
    infoData: Record<string, any> = {};
    
    /**
     * 生成info 对应schmea 数据
     */
    infoSchema: Record<string, JSONSchema> = {};
    
    setInfo(tableId, { fields, tables }: InfoItem){
        this.info[tableId] = { fields, tables }
        const schema: JSONSchema = { type: "object", properties: {} };
        const data = {};
        for (const item of fields) {
            schema.properties[item.value] = {
                type: "string",
                description: `${item.fieldComment || item.fieldName}(${item.value})`
            }
            data[item.value] = "";
        }
        this.infoSchema[tableId] = { type: "object", properties: { data: schema }};
        this.infoData[tableId] = { data }; 
    }

}

export default new Store();