import React from 'react';
/**
 * 这边是为了记录业务表单的信息，为了选择表单字段信息的交互
 */
interface TableFieldItem {
    fieldName: string; // 字段名称
    value: string; // 字段值
}
interface FieldItem extends TableFieldItem {
    createDtm?: number; // 创建时间
    createUser?: string; // 创建人
    fieldComment?: string; // 字段备注
    fieldType?: string; // 字段类型
    // fieldName?: string; // 字段名
    // value?: string; //字段值
}

interface RelationItem {
    cColumnName: string; 
    id: string;
    mColumnName: string;
    relationLineId: string;
    relationShip: string;
}

interface TableItem {
    cTableId: string; // 表格id
    tableName: string; // 表名称
    customAssociationRelationList: RelationItem[]; // 字表名称数据
    itemTableName: string; // 子表名称
    itemTableFields: TableFieldItem[];
}
export interface FormContextProps{
    fields?: FieldItem[];
    // 当前在子表下面
    itemId?: string;
    tables?: TableItem[];
    modelKey?: string;
}
export const FormBusinessContext = React.createContext<FormContextProps>(null);
